1	package contractsentinel
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件锁定 audit 提交对“JSON 对象内重复成员名”的整体拒绝：
10	// Go 的 encoding/json 对同名成员静默保留最后一个值，因此 invariants 中
11	// false 后再写 true 会只剩通过、null 后写布尔值会绕过非布尔拒绝。
12	// 这类输入没有唯一可信结论，任何一个对象出现重复成员都必须整份拒绝，
13	// 且错误要点名重复成员与所在对象（具体到哪条规则/哪条检查记录）。
14	
15	const dupRulesArtifact = `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`
16	
17	// --- 扫描器本身：在解码后的成员名上判重 ---
18	
19	func TestFindDuplicateInvariantsFalseThenTrue(t *testing.T) {
20		data := []byte(`{"invariants":{"inv":false,"inv":true}}`)
21		dup := findDuplicateJSONMember(data)
22		if dup == nil {
23			t.Fatal("false then true for the same invariant must be detected")
24		}
25		if dup.member != "inv" {
26			t.Fatalf("duplicate member = %q, want inv", dup.member)
27		}
28	}
29	
30	func TestFindDuplicateRejectsEqualValues(t *testing.T) {
31		// 重复值相同也不放行：问题在于成员出现两次，而不是值冲突。
32		data := []byte(`{"invariants":{"inv":true,"inv":true}}`)
33		if findDuplicateJSONMember(data) == nil {
34			t.Fatal("identical repeated values must still be a duplicate")
35		}
36	}
37	
38	func TestFindDuplicateNullThenBool(t *testing.T) {
39		// null 在前、布尔在后：必须在非布尔校验“看到”最后一个值之前拦下。
40		data := []byte(`{"invariants":{"inv":null,"inv":false}}`)
41		if findDuplicateJSONMember(data) == nil {
42			t.Fatal("null then bool must be detected before type validation")
43		}
44	}
45	
46	func TestFindDuplicateUnicodeEscapedName(t *testing.T) {
47		// "inv" 解码后就是 "inv"（0x69 == 'i'）：按解码后的字符串判重。
48		data := []byte(`{"invariants":{"inv":false,"inv":true}}`)
49		dup := findDuplicateJSONMember(data)
50		if dup == nil {
51			t.Fatal("literal name and the same Unicode-escaped name must collide")
52		}
53		if dup.member != "inv" {
54			t.Fatalf("duplicate member must be reported using the decoded name, got %q", dup.member)
55		}
56	}
57	
58	func TestFindDuplicateCaseSensitiveNoTrim(t *testing.T) {
59		// 名称区分大小写：Inv 与 inv 是两个成员。
60		if dup := findDuplicateJSONMember([]byte(`{"invariants":{"Inv":false,"inv":true}}`)); dup != nil {
61			t.Fatalf("Inv and inv are distinct members, got %+v", dup)
62		}
63		// 不修剪空白：" inv " 与 "inv" 是两个成员。
64		if dup := findDuplicateJSONMember([]byte(`{"invariants":{" inv ":false,"inv":true}}`)); dup != nil {
65			t.Fatalf("whitespace-padded names must not be trimmed, got %+v", dup)
66		}
67		// 反过来，完全一致的名称（仅 JSON 外围空白不同）当然算重复。
68		if dup := findDuplicateJSONMember([]byte(`{"invariants":{ "inv" : false, "inv" : true}}`)); dup == nil {
69			t.Fatal("identical names separated by whitespace must collide")
70		}
71	}
72	
73	func TestFindDuplicateEveryObjectKind(t *testing.T) {
74		cases := map[string]string{
75			"top-level":   `{"artifact":{"name":"A"},"artifact":{"name":"B"}}`,
76			"artifact":    `{"artifact":{"name":"A","name":"B"}}`,
77			"invariants":  `{"invariants":{"inv":false,"inv":true}}`,
78			"rule":        `{"rules":[{"id":"r1","version":"1","id":"r1"}]}`,
79			"check":       `{"checks":[{"ruleId":"r1","ruleId":"r1"}]}`,
80			"nested":      `{"invariants":{"inv":{"a":1,"a":2}}}`,
81			"unknown":     `{"mystery":{"a":1,"a":2}}`,
82			"top-unknown": `{"extra":1,"extra":2}`,
83		}
84		for name, input := range cases {
85			if findDuplicateJSONMember([]byte(input)) == nil {
86				t.Errorf("%s: duplicate member not detected in %s", name, input)
87			}
88		}
89	}
90	
91	func TestFindDuplicateSameNameInDifferentObjectsOK(t *testing.T) {
92		// 多条规则各自带 id、多条检查各自带 ruleId，是正常输入，不能误判。
93		input := `{
94			"artifact": {"name":"A"},
95			"rules": [
96				{"id":"r1","version":"1"},
97				{"id":"r2","version":"1"}
98			],
99			"checks": [
100				{"ruleId":"r1","status":"通过"},
101				{"ruleId":"r2","status":"通过"}
102			]
103		}`
104		if dup := findDuplicateJSONMember([]byte(input)); dup != nil {
105			t.Fatalf("equal member names in separate objects are legal: %+v", dup)
106		}
107	}
108	
