package contractsentinel

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// 本文件围绕读取入口 LoadReport 锁定“规则结论 ↔ 缺陷记录”的对应关系：
// 合法报告中每条“发现缺陷”规则恰好对应一条记录；损坏该关系的归档即使
// 报告 id 与归档内容相符（重算 id 后写盘），也必须被当作损坏归档拒绝，
// 而不是靠 id 不匹配才被发现。
//
// 关键手法：storeAndCorrupt 先写出一份 id 与内容完全相符的合法归档，再
